<?php require_once __DIR__.'/../config/config.php';
$u=require_role(['teacher']);$uid=$u['id'];$action=$_GET['action']??$_POST['action']??'list';$method=$_SERVER['REQUEST_METHOD'];
if($action==='list'){$st=db()->prepare('SELECT s.*,COUNT(DISTINCT l.id) lesson_count,COALESCE(SUM(l.price),0) total_fee,(SELECT COUNT(*) FROM student_parents sp WHERE sp.student_id=s.id) parent_count,(SELECT COUNT(*) FROM student_accounts sa WHERE sa.student_id=s.id) student_account_count FROM students s LEFT JOIN lessons l ON l.student_id=s.id WHERE s.teacher_id=? GROUP BY s.id ORDER BY s.name');$st->execute([$uid]);json_response(['success'=>true,'students'=>$st->fetchAll()]);}
if($action==='save'&&$method==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$class=trim($_POST['class_name']??'');$phone=trim($_POST['parent_phone']??'');$note=trim($_POST['note']??'');if($name==='')json_response(['success'=>false,'message'=>'Họ tên không được để trống.'],422);if($id){own_student($id,$uid);$st=db()->prepare('UPDATE students SET name=?,class_name=?,parent_phone=?,note=? WHERE id=? AND teacher_id=?');$st->execute([$name,$class,$phone,$note,$id]);}else{$st=db()->prepare('INSERT INTO students(teacher_id,name,class_name,parent_phone,note,connection_code) VALUES(?,?,?,?,?,?)');$st->execute([$uid,$name,$class,$phone,$note,connection_code()]);$id=(int)db()->lastInsertId();}json_response(['success'=>true,'id'=>$id]);}
if($action==='delete'&&$method==='POST'){$id=(int)($_POST['id']??0);own_student($id,$uid);db()->prepare('DELETE FROM students WHERE id=? AND teacher_id=?')->execute([$id,$uid]);json_response(['success'=>true]);}
if($action==='regenerate_code'&&$method==='POST'){$id=(int)($_POST['id']??0);own_student($id,$uid);$code=connection_code();db()->prepare('UPDATE students SET connection_code=? WHERE id=? AND teacher_id=?')->execute([$code,$id,$uid]);json_response(['success'=>true,'code'=>$code]);}
json_response(['success'=>false,'message'=>'Action không hợp lệ'],400);
